//! The website's benchmark data and charts are what the repository would
//! export.
//!
//! The site vendors `_data/bench/latest.json` (and one file per Miri version)
//! and the SVG charts under `assets/bench/<version>/`, generated by
//! `bench/export_site.py` from the newest publication run committed under
//! `bench/results/`. This runs the export's `--check` mode, which renders a
//! fresh copy and compares it byte for byte, so a hand-edited number or a
//! chart left over from an older run fails here. It skips with a log line
//! when the sibling `../miri-lang.org` checkout is absent, or when `python3`
//! with matplotlib is not installed.

use std::path::PathBuf;
use std::process::Command;

fn repo_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn website_root() -> Option<PathBuf> {
    let site = repo_root().parent()?.join("miri-lang.org");
    site.is_dir().then_some(site)
}

fn matplotlib_available() -> bool {
    Command::new("python3")
        .args(["-c", "import matplotlib"])
        .output()
        .is_ok_and(|output| output.status.success())
}

#[test]
fn website_benchmark_data_matches_a_fresh_export() {
    let Some(site) = website_root() else {
        eprintln!(
            "skipping site-identity gate: sibling website repo (../miri-lang.org) not present"
        );
        return;
    };
    if !matplotlib_available() {
        eprintln!("skipping site-identity gate: python3 with matplotlib is not installed");
        return;
    }
    let root = repo_root();
    let output = Command::new("python3")
        .arg(root.join("bench").join("export_site.py"))
        .arg("--check")
        .arg("--site")
        .arg(&site)
        .current_dir(&root)
        .output()
        .expect("python3 runs");
    println!("{}", String::from_utf8_lossy(&output.stdout));
    assert!(
        output.status.success(),
        "the website's benchmark data is stale; run `python3 bench/export_site.py`:\n{}",
        String::from_utf8_lossy(&output.stderr)
    );
}
